CREATE TYPE "lesson_block_type" AS ENUM ('RICH_TEXT', 'VOCABULARY', 'GRAMMAR', 'MEDIA', 'QUESTION_SET', 'PRONUNCIATION');
CREATE TABLE "courses" ("id" uuid PRIMARY KEY, "slug" varchar(128) NOT NULL UNIQUE, "title" varchar(255) NOT NULL, "description" text, "status" content_status NOT NULL DEFAULT 'DRAFT', "content_batch_id" uuid REFERENCES "content_batches"("id"), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "course_levels" ("id" uuid PRIMARY KEY, "course_id" uuid NOT NULL REFERENCES "courses"("id") ON DELETE CASCADE, "cefr_level" varchar(2) NOT NULL, "sort_order" integer NOT NULL, "title" varchar(255) NOT NULL);
CREATE TABLE "course_units" ("id" uuid PRIMARY KEY, "course_level_id" uuid NOT NULL REFERENCES "course_levels"("id") ON DELETE CASCADE, "slug" varchar(128) NOT NULL, "title" varchar(255) NOT NULL, "sort_order" integer NOT NULL, CONSTRAINT "course_units_level_slug_idx" UNIQUE("course_level_id", "slug"));
CREATE TABLE "lessons" ("id" uuid PRIMARY KEY, "unit_id" uuid NOT NULL REFERENCES "course_units"("id") ON DELETE CASCADE, "slug" varchar(128) NOT NULL, "title" varchar(255) NOT NULL, "skill" varchar(16), "estimated_minutes" integer NOT NULL, "status" content_status NOT NULL DEFAULT 'DRAFT', "content_batch_id" uuid REFERENCES "content_batches"("id"), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "lessons_unit_slug_idx" UNIQUE("unit_id", "slug"));
CREATE TABLE "lesson_blocks" ("id" uuid PRIMARY KEY, "lesson_id" uuid NOT NULL REFERENCES "lessons"("id") ON DELETE CASCADE, "type" lesson_block_type NOT NULL, "sort_order" integer NOT NULL, "schema_version" integer NOT NULL, "content" jsonb NOT NULL);
CREATE TABLE "vocabulary" ("id" uuid PRIMARY KEY, "headword" varchar(255) NOT NULL, "part_of_speech" varchar(64), "cefr_level" varchar(2), "ipa" varchar(255), "meaning" text, "example" text, "audio_media_id" uuid, "tags" jsonb NOT NULL DEFAULT '[]'::jsonb, "status" content_status NOT NULL DEFAULT 'DRAFT', "content_batch_id" uuid REFERENCES "content_batches"("id"), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "vocabulary_headword_pos_idx" UNIQUE("headword", "part_of_speech"));
CREATE TABLE "vocabulary_reviews" ("id" uuid PRIMARY KEY, "user_id" uuid NOT NULL, "vocabulary_id" uuid NOT NULL REFERENCES "vocabulary"("id") ON DELETE CASCADE, "due_at" timestamptz NOT NULL, "last_review" timestamptz, "difficulty" real NOT NULL, "stability" real NOT NULL, "retrievability" real NOT NULL, "elapsed_days" integer NOT NULL, "scheduled_days" integer NOT NULL, "learning_steps" integer NOT NULL, "repetitions" integer NOT NULL, "lapses" integer NOT NULL, "fsrs_state" integer NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "vocabulary_reviews_user_vocab_idx" UNIQUE("user_id", "vocabulary_id"));
